#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 72
#define NCT 256

typedef float v8 __attribute__((vector_size(32)));

static inline v8 ld8(const float *p) { v8 v; memcpy(&v, p, sizeof(v)); return v; }
static inline void st8(float *p, v8 v) { memcpy(p, &v, sizeof(v)); }

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int accum)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        v8 a0;
        a0 = (v8){0} + a[0]; c00 += a0 * b0; c01 += a0 * b1;
        a0 = (v8){0} + a[1]; c10 += a0 * b0; c11 += a0 * b1;
        a0 = (v8){0} + a[2]; c20 += a0 * b0; c21 += a0 * b1;
        a0 = (v8){0} + a[3]; c30 += a0 * b0; c31 += a0 * b1;
        a0 = (v8){0} + a[4]; c40 += a0 * b0; c41 += a0 * b1;
        a0 = (v8){0} + a[5]; c50 += a0 * b0; c51 += a0 * b1;
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        float *r;
        if (accum) {
            r = c;           st8(r, ld8(r) + c00); st8(r + 8, ld8(r + 8) + c01);
            r = c + ldc;     st8(r, ld8(r) + c10); st8(r + 8, ld8(r + 8) + c11);
            r = c + 2 * ldc; st8(r, ld8(r) + c20); st8(r + 8, ld8(r + 8) + c21);
            r = c + 3 * ldc; st8(r, ld8(r) + c30); st8(r + 8, ld8(r + 8) + c31);
            r = c + 4 * ldc; st8(r, ld8(r) + c40); st8(r + 8, ld8(r + 8) + c41);
            r = c + 5 * ldc; st8(r, ld8(r) + c50); st8(r + 8, ld8(r + 8) + c51);
        } else {
            r = c;           st8(r, c00); st8(r + 8, c01);
            r = c + ldc;     st8(r, c10); st8(r + 8, c11);
            r = c + 2 * ldc; st8(r, c20); st8(r + 8, c21);
            r = c + 3 * ldc; st8(r, c30); st8(r + 8, c31);
            r = c + 4 * ldc; st8(r, c40); st8(r + 8, c41);
            r = c + 5 * ldc; st8(r, c50); st8(r + 8, c51);
        }
    } else {
        float tmp[MR * NR] __attribute__((aligned(32)));
        st8(tmp + 0 * NR, c00); st8(tmp + 0 * NR + 8, c01);
        st8(tmp + 1 * NR, c10); st8(tmp + 1 * NR + 8, c11);
        st8(tmp + 2 * NR, c20); st8(tmp + 2 * NR + 8, c21);
        st8(tmp + 3 * NR, c30); st8(tmp + 3 * NR + 8, c31);
        st8(tmp + 4 * NR, c40); st8(tmp + 4 * NR + 8, c41);
        st8(tmp + 5 * NR, c50); st8(tmp + 5 * NR + 8, c51);
        for (int i = 0; i < mr; i++)
            for (int j = 0; j < nr; j++) {
                if (accum) c[i * ldc + j] += tmp[i * NR + j];
                else       c[i * ldc + j]  = tmp[i * NR + j];
            }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npanels = (n + NR - 1) / NR;
    int npad = npanels * NR;
    int kcmax = n < KC ? n : KC;

    size_t bbytes = (size_t)kcmax * npad * sizeof(float);
    bbytes = (bbytes + 63) & ~(size_t)63;
    float *Bp = (float *)aligned_alloc(64, bbytes);

    int nib = (n + MC - 1) / MC;
    int njb = (n + NCT - 1) / NCT;

    #pragma omp parallel
    {
        float *Ap = (float *)aligned_alloc(64, (size_t)MC * KC * sizeof(float));

        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int accum = pc > 0;

            /* pack B block: panels of NR columns, each kc x NR contiguous */
            #pragma omp for schedule(static)
            for (int p = 0; p < npanels; p++) {
                int j0 = p * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                float *dst = Bp + (size_t)p * kc * NR;
                const float *src = B + (size_t)pc * n + j0;
                if (nr == NR) {
                    for (int k = 0; k < kc; k++)
                        memcpy(dst + k * NR, src + (size_t)k * n, NR * sizeof(float));
                } else {
                    for (int k = 0; k < kc; k++) {
                        int j = 0;
                        for (; j < nr; j++) dst[k * NR + j] = src[(size_t)k * n + j];
                        for (; j < NR; j++) dst[k * NR + j] = 0.0f;
                    }
                }
            }

            #pragma omp for schedule(dynamic) collapse(2)
            for (int ib = 0; ib < nib; ib++) {
                for (int jb = 0; jb < njb; jb++) {
                    int ic = ib * MC;
                    int mc = n - ic < MC ? n - ic : MC;

                    /* pack A block: panels of MR rows, each kc x MR */
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        float *dst = Ap + (size_t)ir * kc;
                        const float *src = A + (size_t)(ic + ir) * n + pc;
                        if (mr == MR) {
                            for (int k = 0; k < kc; k++) {
                                dst[k * MR + 0] = src[k];
                                dst[k * MR + 1] = src[n + k];
                                dst[k * MR + 2] = src[2 * (size_t)n + k];
                                dst[k * MR + 3] = src[3 * (size_t)n + k];
                                dst[k * MR + 4] = src[4 * (size_t)n + k];
                                dst[k * MR + 5] = src[5 * (size_t)n + k];
                            }
                        } else {
                            for (int k = 0; k < kc; k++) {
                                int i = 0;
                                for (; i < mr; i++) dst[k * MR + i] = src[(size_t)i * n + k];
                                for (; i < MR; i++) dst[k * MR + i] = 0.0f;
                            }
                        }
                    }

                    int j0 = jb * NCT;
                    int j1 = j0 + NCT < n ? j0 + NCT : n;
                    for (int jr = j0; jr < j1; jr += NR) {
                        int nr = j1 - jr < NR ? j1 - jr : NR;
                        const float *bp = Bp + (size_t)(jr / NR) * kc * NR;
                        for (int ir = 0; ir < mc; ir += MR) {
                            int mr = mc - ir < MR ? mc - ir : MR;
                            kernel(kc, Ap + (size_t)ir * kc, bp,
                                   C + (size_t)(ic + ir) * n + jr, n, mr, nr, accum);
                        }
                    }
                }
            }
        }
        free(Ap);
    }
    free(Bp);
}
